SELECT "joined_nodes"."id" FROM "joined_nodes" WHERE EXISTS(SELECT 1 FROM "joined_nodes" AS "foundry_related_6" INNER JOIN "joined_nodes" AS "foundry_link_6" ON ("foundry_related_6"."id" = "foundry_link_6"."id") WHERE ("foundry_related_6"."id" = $1) AND EXISTS(SELECT 1 FROM "joined_nodes" AS "foundry_related_5" INNER JOIN "joined_nodes" AS "foundry_link_5" ON ("foundry_related_5"."id" = "foundry_link_5"."id") WHERE ("foundry_related_5"."id" = $2) AND EXISTS(SELECT 1 FROM "joined_nodes" AS "foundry_related_4" INNER JOIN "joined_nodes" AS "foundry_link_4" ON ("foundry_related_4"."id" = "foundry_link_4"."id") WHERE ("foundry_related_4"."id" = $3) AND EXISTS(SELECT 1 FROM "joined_nodes" AS "foundry_related_3" INNER JOIN "joined_nodes" AS "foundry_link_3" ON ("foundry_related_3"."id" = "foundry_link_3"."id") WHERE ("foundry_related_3"."id" = $4) AND EXISTS(SELECT 1 FROM "joined_nodes" AS "foundry_related_2" INNER JOIN "joined_nodes" AS "foundry_link_2" ON ("foundry_related_2"."id" = "foundry_link_2"."id") WHERE ("foundry_related_2"."id" = $5) AND EXISTS(SELECT 1 FROM "joined_nodes" AS "foundry_related" INNER JOIN "joined_nodes" AS "foundry_link" ON ("foundry_related"."id" = "foundry_link"."id") WHERE ("foundry_related"."id" = $6) AND ("foundry_link"."id" = "foundry_related_2"."id")) AND ("foundry_link_2"."id" = "foundry_related_3"."id")) AND ("foundry_link_3"."id" = "foundry_related_4"."id")) AND ("foundry_link_4"."id" = "foundry_related_5"."id")) AND ("foundry_link_5"."id" = "foundry_related_6"."id")) AND ("foundry_link_6"."id" = "joined_nodes"."id"))
